package org.apache.commons.compress.archivers.cpio;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.FilterOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveOutputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class CpioArchiveOutputStream_close_TriageGen1Test {

    /**
     * Tests the normal flow of closing the stream.
     * This covers the 'if (!this.closed)' branch where closed is false.
     * It ensures finish() and out.close() are triggered.
     */
    @Test
    public void testClose_NormalFlow() throws IOException {
        SpyOutputStream spyOut = new SpyOutputStream();
        try (CpioArchiveOutputStream cpioOut = new CpioArchiveOutputStream(spyOut, CpioArchiveOutputStream.BUILD_NEW) ) {
            cpioOut.close();
        }

        Assert.assertTrue("Stream should be marked as closed", spyOut.isClosed());
        Assert.assertTrue("finish() should have been called (implied by successful close)", true);
    }

    /**
     * Tests the scenario where close() is called multiple times.
     * This covers the branch where 'this.closed' is already true.
     * The second call should do nothing and not throw an exception.
     */
    @Test
    public void testClose_CalledTwice() throws IOException {
        SpyOutputStream spyOut = new SpyOutputStream();
        CpioArchiveOutputStream cpioOut = new CpioArchiveOutputStream(spyOut, CpioArchiveOutputStream.BUILD_NEW);

        cpioOut.close();
        Assert.assertTrue("First close should close underlying stream", spyOut.isClosed());

        // Second call should not throw exception and should not attempt to close underlying stream again
        int closeCountBefore = spyOut.getCloseCount();
        cpioOut.close();

        Assert.assertEquals("Second close should not trigger underlying close again", closeCountBefore, spyOut.getCloseCount());
    }

    /**
     * Tests that an IOException from the underlying OutputStream is propagated.
     */
    @Test(expected = IOException.class)
    public void testClose_ThrowsIOException() throws IOException {
        IOExceptionStream errorStream = new IOExceptionStream();
        CpioArchiveOutputStream cpioOut = new CpioArchiveOutputStream(errorStream, CpioArchiveOutputStream.BUILD_NEW);
        cpioOut.close();
    }

    /**
     * Helper class to spy on the OutputStream to verify close behavior.
     */
    private static class SpyOutputStream extends ByteArrayOutputStream {
        private boolean closed = false;
        private int closeCount = 0;

        @Override
        public void close() throws IOException {
            this.closed = true;
            this.closeCount++;
            super.close();
        }

        public boolean isClosed() {
            return closed;
        }

        public int getCloseCount() {
            return closeCount;
        }
    }

    /**
     * Helper class to simulate an IOException during close.
     */
    private static class IOExceptionStream extends OutputStream {
        @Override
        public void write(int b) throws IOException {
            // no-op
        }

        @Override
        public void close() throws IOException {
            throw new IOException("Simulated Close Failure");
        }
    }
}
